D."name", "name_ur" = EXCLUDED."name_ur", "birth" = EXCLUDED."birth", "death" = EXCLUDED."death", "birthplace" = EXCLUDED."birthplace", "residence" = EXCLUDED."residence", "spouse" = EXCLUDED."spouse", "spouse_ur" = EXCLUDED."spouse_ur", "notes" = EXCLUDED."notes", "notes_ur" = EXCLUDED."notes_ur", "tag" = EXCLUDED."tag", "locked" = EXCLUDED."locked", "sort_order" = EXCLUDED."sort_order", "updated_at" = EXCLUDED."updated_at", "birth_ur" = EXCLUDED."birth_ur", "death_ur" = EXCLUDED."death_ur", "birthplace_ur" = EXCLUDED."birthplace_ur", "residence_ur" = EXCLUDED."residence_ur", "pending_count" = EXCLUDED."pending_count", "photo" = EXCLUDED."photo", "photo_caption" = EXCLUDED."photo_caption", "photo_caption_ur" = EXCLUDED."photo_caption_ur", "birth_order" = EXCLUDED."birth_order";
